package com.example.starter.support;

import com.example.starter.repo.IdempotencyRepository;
import com.example.starter.web.ConflictException;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Component;

import java.time.Clock;

/**
 * requestId 幂等执行模板。调用方须处于事务内：
 * <ul>
 *     <li>同键同参：直接返回首次结果（不重复执行业务）；</li>
 *     <li>同键异参：抛出 409；</li>
 *     <li>并发同键：唯一键插入冲突后重读，保证只有一次业务生效。</li>
 * </ul>
 */
@Component
public class IdempotencySupport {

    private final IdempotencyRepository repository;
    private final FingerprintHasher hasher;
    private final ObjectMapper objectMapper;
    private final Clock clock;

    public IdempotencySupport(IdempotencyRepository repository, FingerprintHasher hasher,
                              ObjectMapper objectMapper, Clock clock) {
        this.repository = repository;
        this.hasher = hasher;
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    public <T> T execute(String requestId, String requestKind, Object payload,
                         Class<T> responseType, int successStatus, java.util.function.Supplier<T> action) {
        String fingerprint = hasher.hash(requestId, requestKind, payload);
        var existing = repository.find(requestId);
        if (existing.isPresent()) {
            if (!existing.get().fingerprint().equals(fingerprint)) {
                throw new ConflictException("requestId 已用于不同的业务请求：" + requestId);
            }
            return deserialize(existing.get().responseBody(), responseType);
        }
        T result;
        try {
            result = action.get();
        } catch (DuplicateKeyException e) {
            // 与并发请求在业务唯一键上相撞：重读幂等记录返回首次结果，冲突语义交给业务唯一键的既成事实。
            var winner = repository.find(requestId);
            if (winner.isPresent() && winner.get().fingerprint().equals(fingerprint)) {
                return deserialize(winner.get().responseBody(), responseType);
            }
            throw e;
        }
        try {
            repository.insert(requestId, requestKind, fingerprint, successStatus,
                    objectMapper.writeValueAsString(result), clock.instant());
        } catch (DuplicateKeyException e) {
            var winner = repository.find(requestId).orElseThrow();
            if (!winner.fingerprint().equals(fingerprint)) {
                throw new ConflictException("requestId 已用于不同的业务请求：" + requestId);
            }
            return deserialize(winner.responseBody(), responseType);
        }
        return result;
    }

    private <T> T deserialize(String body, Class<T> type) {
        try {
            return objectMapper.readValue(body, type);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("幂等结果反序列化失败", e);
        }
    }
}

