        assertThat(third.getBody().alarmId()).isNotNull();

        // 预算分配与指令：加热恰用尽预算
        ResponseEntity<CommandDtos.BudgetResponse> budget = restTemplate.postForEntity(
                url("/api/energy/budgets"),
                new CommandDtos.BudgetRequest(ZONE, DAY, new BigDecimal("5.000")),
