);
COMMENT ON TABLE energy_budget IS '每日（UTC日界）分区能耗预算，单位kWh';

CREATE TABLE IF NOT EXISTS control_command (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    zone_code     VARCHAR(64)   NOT NULL,
    command_type  VARCHAR(24)   NOT NULL,
