/**
 * 以新读数为末端，沿采样时刻向前统计在同一生效策略下连续偏离设定带的点数；
 * 恰在连续点数达到 3 时产生一条告警，第 4 个及以后的连续偏离点不再产生告警。
 */
private Long detectDeviation(String zoneCode, Instant sampleTime, Instant now) {
    StrategyRepository.Strategy strategy =
            strategyRepository.findEffectiveAt(zoneCode, sampleTime).orElse(null);
    if (strategy == null) {
        return null;
    }
    List<ReadingRepository.Reading> recent =
            readingRepository.findRecentUntil(zoneCode, sampleTime, SCAN_WINDOW);
    if (recent.isEmpty()) {
        return null;
    }
    int runLength = 0;
    Instant runStart = null;
    for (int i = recent.size() - 1; i >= 0; i--) {
        ReadingRepository.Reading r = recent.get(i);
        StrategyRepository.Strategy effective =
                strategyRepository.findEffectiveAt(zoneCode, r.sampleTime()).orElse(null);
        if (effective == null || !effective.id().equals(strategy.id()) || !isOutOfBand(strategy, r)) {
            break;
        }
        runLength++;
        runStart = r.sampleTime();
    }
    if (runLength != DEVIATION_RUN_TO_TRIGGER) {
        return null;
    }
    long id = alarmRepository.insert(zoneCode, strategy.strategyCode(), runStart, sampleTime,
            runLength, now);
    return id;
}

